const GEOMETRY_BY_CODE = new Map<string, WorldMapCountryGeometry>(
  WORLD_MAP_COUNTRIES.map((item) => [item.code, item]),
);

export function getCountryMapPoint(code: string): { cx: number; cy: number } | null {
  const c = code.trim().toUpperCase();
  const poly = GEOMETRY_BY_CODE.get(c);
  if (poly) return { cx: poly.cx, cy: poly.cy };
  return EXTRA_COUNTRY_COORDS[c] ?? null;
}

export type MapColorStep = 0 | 1 | 2 | 3 | 4;

/**
 * Pure data-driven color bucket (0..4) for a country founder count.
 * Zero founders -> 0. Non-zero founders -> 1..4 scaled against maxCount.
 * No country (including GE) has any hardcoded override.
 */
export function computeCountryColorStep(count: number, maxCount: number): MapColorStep {
  if (!Number.isFinite(count) || count <= 0) return 0;
  const safeMax = Math.max(1, Number.isFinite(maxCount) ? maxCount : 1);
  if (safeMax <= 4) {
    if (count === 1) return 1;
    if (count === 2) return 2;
    if (count === 3) return 3;
    return 4;
  }
  const ratio = count / safeMax;
  if (ratio <= 0.25) return 1;
  if (ratio <= 0.5) return 2;
  if (ratio <= 0.75) return 3;
  return 4;
}

export type MapLegendBucket = {
  step: MapColorStep;
  label: string;
};

export function buildMapLegendBuckets(maxCount: number, lang = "en"): MapLegendBucket[] {
  const fmt = (n: number) => n.toLocaleString(lang);
  if (!Number.isFinite(maxCount) || maxCount <= 4) {
    return [
      { step: 0, label: fmt(0) },
      { step: 1, label: fmt(1) },
      { step: 2, label: fmt(2) },
      { step: 3, label: fmt(3) },
      { step: 4, label: `${fmt(4)}+` },
    ];
  }
  const q1 = Math.max(1, Math.floor(maxCount * 0.25));
  const q2 = Math.max(q1 + 1, Math.floor(maxCount * 0.5));
  const q3 = Math.max(q2 + 1, Math.floor(maxCount * 0.75));
  return [
    { step: 0, label: fmt(0) },
    { step: 1, label: q1 === 1 ? fmt(1) : `${fmt(1)}–${fmt(q1)}` },
    { step: 2, label: q2 === q1 + 1 ? fmt(q2) : `${fmt(q1 + 1)}–${fmt(q2)}` },
    { step: 3, label: q3 === q2 + 1 ? fmt(q3) : `${fmt(q2 + 1)}–${fmt(q3)}` },
    { step: 4, label: `${fmt(q3 + 1)}–${fmt(Math.max(q3 + 1, maxCount))}` },
  ];
}
